import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import '../styles/ManageGigs.css';

const ManageGigPostings = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [gigs, setGigs] = useState([]);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchGigs = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/gigs');
        setGigs(response.data);
        console.log("Fetched gigs:", response.data);
      } catch (error) {
        console.error('Error fetching gigs:', error);
      }
    };

    fetchGigs();
  }, []);

  const handleDelete = async (gigId) => {
    if (!window.confirm("Are you sure you want to delete this gig?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/gigs/${gigId}`);
      setGigs((prev) => prev.filter((gig) => gig._id !== gigId));
    } catch (error) {
      console.error("Error deleting gig:", error);
    }
  };

  const filteredGigs = gigs.filter((gig) =>
    gig.username?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="manage-gig-container">
      <h2 className="manage-title">Manage Gig Postings</h2>
      <input
        type="text"
        className="search-input"
        placeholder="Search by username..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      <div className="gig-list">
        {filteredGigs.length === 0 ? (
          <p className="no-gigs-message">No gigs found.</p>
        ) : (
          filteredGigs.map((gig) => (
            <div className="gig-item" key={gig._id}>
              <div className="gig-title">{gig.title || "Untitled Gig"}</div>
              <div className="gig-subtext">
                <strong>Posted By:</strong> {gig.username || "N/A"}
              </div>
              <div className="gig-subtext">
                <strong>Expires:</strong> {gig.expiryDate?.split('T')[0] || "N/A"}
              </div>
              <div className="gig-actions">
                <button className="view-button" onClick={() => navigate(`/gig/${gig._id}`)}>
                  View Gig
                </button>
                <button className="delete-button" onClick={() => handleDelete(gig._id)}>
                  Delete Gig
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ManageGigPostings;
